                ChannelContext(node=value, channel_slug=root.channel_slug)
                for value in values
            ]

        return (
            AttributeValuesByAttributeIdWithLimitLoader(info.context, limit=limit)
            .load(attr.id)
            .then(map_channel_context)
        )

