    staff_api_client,
    permission_group_manage_orders,
    orders,
):
    # given
    query = """
        query ($where: OrderWhereInput!, $filter: OrderFilterInput!) {
            orders(first: 10, where: $where, filter: $filter) {
                totalCount
                edges {
                    node {
                        id
                    }
                }
            }
        }
    """
    variables = {
