from ..enums import ProductAttributeType

QUERY_PRODUCT_AND_VARIANTS_ATTRIBUTES = """
    query ($channel: String){
      products(first: 1, channel: $channel) {
        edges {
          node {
            attributes {
              attribute {
                slug
                type
              }
              values {
