                    }
                }
              }
            }
            variants {
              attributes {
                attribute {
                  slug
                  type
                }
                values {
                  slug
                  reference
                  referencedObject {
                    __typename
                    ... on Page {
                        id
                        publicationDate
                    }
                    ... on ProductVariant {
                        id
                        created
                    }
                    ... on Product {
                        id
                        created
                    }
                  }
                }
              }
            }
          }
        }
