                .then(with_listings)
            )

        return ChannelByIdLoader(info.context).load(order.channel_id).then(with_channel)

    class Meta:
        root_type = None
        enable_dry_run = False
        interfaces = (Event,)
        description = "Filter shipping methods for order."
        doc_category = DOC_CATEGORY_ORDERS


