        )
        return

    if not attr_values.dropdown:
        if attribute.value_required:
            attribute_errors[AttributeInputErrors.ERROR_NO_VALUE_GIVEN].append(
                attr_identifier
            )
    else:
        validate_single_selectable_field(
            attribute,
            attr_values.dropdown,
            attribute_errors,
            attr_identifier,
        )


