def test_pages_query_with_multiple_attribute_filters(
    attribute_where_input,
    expected_count_result,
    staff_api_client,
    page_list,
    page_type,
    size_page_attribute,
    tag_page_attribute,
    author_page_attribute,
    boolean_attribute,
):
    # given
