def test_customers_filter_by_date_joined(
    where,
    indexes,
    staff_api_client,
    permission_group_manage_users,
    customer_user,
):
    # given
    with freeze_time((timezone.now() - datetime.timedelta(days=5)).isoformat()):
        customer_2 = User.objects.create_user(
            "test2@example.com",
            "password",
            first_name="Leslie",
            last_name="Wade",
