    with freeze_time((timezone.now() - datetime.timedelta(days=2)).isoformat()):
        customer_3 = User.objects.create_user(
            "test3@example.com",
            "password",
            first_name="John",
            last_name="Lee",
        )

    customer_list = [customer_user, customer_2, customer_3]

